                    const realRel = path.relative(realSkillRoot, realFullPath);
                    if (realRel.startsWith('..') || path.isAbsolute(realRel)) {
                        return {
                            passed: false,
                            error: `Guard function path escapes skill directory: ${guardFunctionPath}`,
                        };
                    }
